<?php
require_once __DIR__.'/_common.php';
$rows=sponsor_rows($conn,"SELECT p.id,p.name,p.type,p.description,p.status,p.start_date,p.end_date,p.duration,COUNT(DISTINCT c.id) cohorts,COALESCE(SUM(c.max_capacity),0) capacity,COALESCE(SUM(c.applications_count),0) cohort_applications FROM programmes p LEFT JOIN cohorts c ON c.programme_id=p.id GROUP BY p.id,p.name,p.type,p.description,p.status,p.start_date,p.end_date,p.duration ORDER BY FIELD(p.status,'active','paused','draft','completed','archived'),p.start_date DESC,p.name");
sponsor_header('Programme register','programmes','Browse programme status, delivery dates, cohort coverage and planned capacity.'); ?>
<div class="sp-card"><div class="sp-toolbar"><input class="sp-search" data-search="#programmeTable" placeholder="Search programme, type or status…" aria-label="Search programmes"><span class="sp-muted"><?= count($rows) ?> programme records</span><a class="sp-btn" href="<?= url('sponsor/export.php?dataset=programmes') ?>">↓ Export CSV</a></div><div class="sp-tablewrap"><table id="programmeTable"><thead><tr><th>Programme</th><th>Status</th><th>Cohorts</th><th>Planned capacity</th><th>Cohort application count*</th><th>Timeline</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= sponsor_e($r['name']) ?></strong><div class="sp-muted" style="font-size:11px;margin-top:4px"><?= sponsor_e(sponsor_status((string)$r['type'])) ?><?= $r['duration']?' · '.sponsor_e($r['duration']):'' ?></div><div class="sp-muted" style="max-width:380px;font-size:11px;margin-top:6px"><?= sponsor_e($r['description'] ?: 'No description provided.') ?></div></td><td><span class="sp-pill <?= sponsor_e($r['status']) ?>"><?= sponsor_e(sponsor_status((string)$r['status'])) ?></span></td><td><?= (int)$r['cohorts'] ?></td><td><?= number_format((int)$r['capacity']) ?></td><td><?= number_format((int)$r['cohort_applications']) ?></td><td><?= sponsor_e(sponsor_date($r['start_date'])) ?><br><span class="sp-muted">to <?= sponsor_e(sponsor_date($r['end_date'])) ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="sp-empty">No programme records found.</td></tr><?php endif; ?></tbody></table></div></div><p class="sp-footnote">*Sum of the cohort-level applications_count field; this may differ from the application table total. No records are modified from the Sponsor Portal.</p>
<?php sponsor_footer(); ?>
